#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""独立反向复核复算脚本：《大奉打更人》第一百零二章 高于生命的东西 [328572,332680)。只读，不写仓库。

用法：  python3 -B -s <本文件> [仓库根]
复算本复核的全部结论：
  · 引文四项元数据 / 3 个哈希 / 区间外 8 条的位置
  · coverage：按候选自述判据复算 19 而非 13（CE1），并列出漏列的 6 段
  · CE2/CE3：『拔刀』『握刀的手一挥』在区间内与候选内的实际计数
  · CE4：crossFieldReuse 的条目级 vs 字段级口径
  · CE5：tasks[2].actionQuotes 的条数
  · 图谱缓存落区间的节点数、固定种子抽样 5 条
"""
import json, hashlib, random, re, sys

ROOT = sys.argv[1] if len(sys.argv) > 1 else '.'
SRC   = 'data/cache/1063b17ca65ec1b76f30e460.docs.json'
GC    = 'data/cache/1063b17ca65ec1b76f30e460.json'
CANDF = 'loop/state/out/read_dafeng_L1_0101.candidate.json'
SCOPE = ('tasks','causeEdges','states','knowledgeDiffs','foreshadows','worldSettings','themeReadings')
S, E = 328572, 332680

t = json.load(open(ROOT + '/' + SRC))[0]['text']
c = json.load(open(ROOT + '/' + CANDF))
raw = open(ROOT + '/' + CANDF, encoding='utf-8').read()

# ── 引文收集：两种范围，分别报告 ─────────────────────────────────────────
def collect(include_selfcheck):
    out = []
    def walk(n):
        if isinstance(n, dict):
            if isinstance(n.get('quote'), str) and 'start' in n and 'end' in n:
                out.append(n)
            for v in n.values():
                walk(v)
        elif isinstance(n, list):
            for v in n:
                walk(v)
    for k, v in c.items():
        if k == 'selfCheck' and not include_selfcheck:
            continue
        walk(v)
    return out

def collect_scope():
    """README 口径：跨条目复用只看 7 个内容分区（候选自己声明的范围）。"""
    out = []
    def walk(n, entry):
        if isinstance(n, dict):
            if isinstance(n.get('quote'), str) and 'start' in n and 'end' in n:
                out.append((entry, n))
            for v in n.values():
                walk(v, entry)
        elif isinstance(n, list):
            for v in n:
                walk(v, entry)
    for k in SCOPE:
        for i, item in enumerate(c[k]):
            walk(item, '%s[%d]' % (k, i))
    return out

refs_all = collect(True)
refs_content = collect(False)
print('=== 引文实例数 ===')
print('全树（含 selfCheck）      refs=%d distinct=%d' % (len(refs_all), len({(r['quote'], r['start'], r['end']) for r in refs_all})))
print('候选声明口径（不含selfCheck）refs=%d distinct=%d  ← 与 selfCheck 自报 210/117 对照'
      % (len(refs_content), len({(r['quote'], r['start'], r['end']) for r in refs_content})))
print('slice!=quote            ', sum(1 for r in refs_all if t[r['start']:r['end']] != r['quote']))
uniq1 = [r for r in refs_all if t.count(r['quote']) == 1]
print('唯一命中引文的声明偏移不是真实命中', sum(1 for r in uniq1 if t.find(r['quote']) != r['start']))
multi = sorted({(r['quote'], r['start'], r['end']) for r in refs_all if t.count(r['quote']) > 1})
print('多命中引文条数            ', len(multi))
print('多命中引文（逐条核对声明的是区间内那一次）:')
for q, s, e in multi:
    hits = [m.start() for m in re.finditer(re.escape(q), t)]
    print('   [%d,%d) occ=%d hits=%s 声明命中=%s' % (s, e, t.count(q), hits[:5], t[s:e] == q))
print('occ mismatch            ', sum(1 for r in refs_all if r.get('occurrencesInFullText') != t.count(r['quote'])))
print('inRange mismatch        ', sum(1 for r in refs_all if bool(r.get('inRange')) != (S <= r['start'] and r['end'] <= E)))
CH = [(m.start(), m.group(0)) for m in re.finditer('第[一二三四五六七八九十百千零]+章[^\n]*', t)]
def chap_at(off):
    cur = None
    for x, h in CH:
        if x <= off:
            cur = h
        else:
            break
    return cur
print('chapterAtOffset mismatch', sum(1 for r in refs_all
      if r.get('inRange') is False and r.get('chapterAtOffset') != chap_at(r['start'])))
print('slice sha ok            ', hashlib.sha256(t[S:E].encode()).hexdigest() == c['source']['sliceSha256'])
print('source sha              ', hashlib.sha256(open(ROOT + '/' + SRC, 'rb').read()).hexdigest())

# 区间外引文位置
print()
print('=== 区间外引文的位置（依据位不允许出现）===')
bad = []
for ti, task in enumerate(c['tasks']):
    for slot in ('objective','obstacle','action','result','cost'):
        for q in task.get(slot + 'Quotes') or []:
            if q.get('inRange') is False:
                bad.append(('tasks[%d].%s' % (ti, slot), q['start']))
for ci, e in enumerate(c['causeEdges']):
    for q in e.get('triggerQuotes') or []:
        if q.get('inRange') is False:
            bad.append(('causeEdges[%d]' % ci, q['start']))
for si, st in enumerate(c['states']):
    qs = (st.get('beforeQuotes') or []) + (st.get('afterQuotes') or []) + ([st['anchorQuote']] if st.get('anchorQuote') else [])
    for q in qs:
        if q.get('inRange') is False:
            bad.append(('states[%d]' % si, q['start']))
for ki, kd in enumerate(c['knowledgeDiffs']):
    for slot in ('knowsQuote','notKnowsQuote'):
        q = kd.get(slot)
        if q and q.get('inRange') is False:
            bad.append(('knowledgeDiffs[%d].%s' % (ki, slot), q['start']))
print('依据位里的区间外引文:', bad if bad else '0 条')

# ── coverage（CE1）──────────────────────────────────────────────────────
print()
print('=== coverage 复算（CE1）===')
lines, pos = [], 0
for ln in t[S:E].split('\n'):
    st = S + pos; en = st + len(ln); pos += len(ln) + 1
    if ln.strip():
        lines.append((st, en, ln))
iv = [(r['start'], r['end']) for r in refs_all if r.get('inRange') is True]
un = [(a, b, x) for a, b, x in lines if not any(not (b <= s or a >= e) for s, e in iv)]
claimed = {(i['start'], i['end']) for i in c['coverageGaps']['items']}
print('非空行 %d ；untouched 复算 %d ；候选自报 %d' % (len(lines), len(un), c['coverageGaps']['untouchedCount']))
print('复算为未触及、但候选没列出的段:')
for a, b, x in un:
    if (a, b) not in claimed:
        print('   [%d,%d) %r' % (a, b, x[:52]))

# ── CE2 / CE3 ──────────────────────────────────────────────────────────
print()
print('=== 措辞反例（CE2/CE3）===')
for w in ('拔刀','自缚','请罪','在鞘中','握刀的手一挥','抄家！'):
    print('  %-8s inRange=%d full=%d candidate_raw=%d' % (w, t[S:E].count(w), t.count(w), raw.count(w)))
print('  states[1].after =', c['states'][1]['after'][:60])
print('  worldSettings[4].explain 含「不改写成现代汉语的『拔刀攻击』」:',
      '不改写成现代汉语' in c['worldSettings'][4]['explain'])
for i, w in enumerate(c['worldSettings']):
    if w.get('institution') in ('declared','executed') or '抄家令' in w.get('name',''):
        print('  worldSettings[%d] %-22s institution=%s hasQuote=%s'
              % (i, w['name'][:20], w.get('institution'), 'quote' in w))
print('  抄家令条目的 quote 承载的是 executed 半边；declared 半边只出现在 explain 里（raw 计数见上）')

# ── CE4 / CE5 ──────────────────────────────────────────────────────────
print()
print('=== CE4 crossFieldReuse 口径 / CE5 条数 ===')
groups = {}
for entry, r in collect_scope():
    groups.setdefault((r['quote'], r['start'], r['end']), set()).add(entry)
reused = {k: sorted(v) for k, v in groups.items() if len(v) >= 2}
print('条目级跨条目复用复算 %d ；候选自报 %d' % (len(reused), c['selfCheck']['crossFieldReuse']['distinctQuotesReusedAcrossEntries']))
listed = {(i['quote'], i['start'], i['end']): i for i in c['selfCheck']['crossFieldReuse']['items']}
print('候选漏列:', sorted(set(reused) - set(listed)))
bad_count = []
for k, i in listed.items():
    if k in reused and i['count'] != len(reused[k]):
        bad_count.append((k[1], i['count'], len(reused[k])))
print('count != 不同条目数 的条目:', bad_count if bad_count else '无')
print('tasks[2].actionQuotes 条数 =', len(c['tasks'][2]['actionQuotes']),
      '；actionNote 自称:', c['tasks'][2]['actionNote'][:14])

# ── 图谱缓存与抽样 ──────────────────────────────────────────────────────
print()
print('=== 图谱缓存 / 固定种子抽样 ===')
g = json.load(open(ROOT + '/' + GC))
for k in ('events','tasks','causeEdges','characterStates','clues','storylines'):
    n = sum(1 for x in (g.get(k) or [])
            if isinstance(x.get('quoteRef'), dict) and isinstance(x['quoteRef'].get('start'), int) and S <= x['quoteRef']['start'] < E)
    print('  cache %-16s %d' % (k, n))
uniq = {}
for r in refs_all:
    uniq.setdefault((r['quote'], r['start'], r['end']), r)
random.seed(101)
hit = 0
for k in random.sample(sorted(uniq), 5):
    r = uniq[k]
    ok = t[r['start']:r['end']] == r['quote'] and t.find(r['quote']) == r['start']
    hit += ok
    print('  sample %-18s [%d,%d) sliceEqual=%s offsetHit=%s occ=%d'
          % (r.get('label'), r['start'], r['end'], t[r['start']:r['end']] == r['quote'], t.find(r['quote']) == r['start'], t.count(r['quote'])))
print('  抽样命中 %d/5' % hit)
